EXPORT ZZT_STCX() BEGIN
LOCAL R,out:={};

R:=stddev({1+i,3-i}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev({1-i,3+i}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev({i,3*i}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev({1+i,3+i}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev({1+i,1+i}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev({(1,1),(3,-1)}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev({1+i}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev(1+i); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev({1+i,2-i,-1+3*i}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
RETURN out; END;

EXPORT ZZT_STCX() BEGIN
LOCAL R,out:={};

R:=stddev({1+i,3-i},{.5,1.5}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev({1+i,3-i},{-.5,1.5}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev({1+i,3-i},{.2,.2}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev({1+i,3-i},{0,1}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev({1+i,3-i},[.5,1.5]); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev({1+i,2-i,-1+3*i},{.25,.5,2.5}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev({1+i,3-i},{-.25,-.75}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
RETURN out; END;

EXPORT ZZT_STCX() BEGIN
LOCAL R,out:={};

R:=stddev({1+i,3-i},{0,0}); out:=CONCAT(out,{{TYPE(R),STRING(R)}});
R:=stddev({1+i,3-i},{-.5,.5}); out:=CONCAT(out,{{TYPE(R),STRING(R)}});
R:=stddev({1+i,3-i},{-1,1}); out:=CONCAT(out,{{TYPE(R),STRING(R)}});
R:=stddev({1.5+i,3-i},{-1,1}); out:=CONCAT(out,{{TYPE(R),STRING(R)}});
R:=stddev({1+.5*i,3-i},{-1,1}); out:=CONCAT(out,{{TYPE(R),STRING(R)}});
R:=stddev({1+i,"2"},{1,1}); out:=CONCAT(out,{{TYPE(R),STRING(R)}});
R:=stddev({1+i,3-i},{1,"2"}); out:=CONCAT(out,{{TYPE(R),STRING(R)}});
RETURN out; END;

