EXPORT ZZT_STCX() BEGIN
LOCAL R,out:={};

R:=stddev({1,3+.00000001*i}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev({1+i,1+.00000001+3*i}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev({1,3-.00000001*i}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
R:=stddev({-.125+.25*i,.375-.125*i,.875-.0625*i},{.125,.375,2.125}); out:=CONCAT(out,{{TYPE(R),ROUND(RE(R),10),ROUND(IM(R),10)}});
RETURN out; END;
